<script setup lang="ts">import{ref}from 'vue';import{useRouter}from 'vue-router';import{signIn}from '../stores/auth';import{useTask}from '../hooks/useTask';import ErrorNotice from '../components/common/ErrorNotice.vue';const email=ref('analyst@balance.demo'),password=ref('Balance2026!');const router=useRouter();const{error,busy,execute}=useTask();const submit=()=>execute(async()=>{await signIn(email.value,password.value);await router.push('/')});</script><template><div class="login"><section class="login-ticket"><div class="ticket-logo">YY / 原野交通研究所</div><p class="eyebrow">FIELD SAMPLE / NOV 2026</p><h1>让每一份样本，<br>回到城市的比例。</h1><p>样本结构与目标人群之间，<br>需要一套可复算的权重口径。</p><div class="ticket-route"><span>01<br>采样</span><i>→</i><span>02<br>校准</span><i>→</i><span>03<br>复核</span></div><small>匿名合成数据 / 统计研究用途 / 无个人决策</small></section><form @submit.prevent="submit"><p class="eyebrow">RESEARCH ACCESS / 001</p><h2>进入抽样校准席</h2><p>检查代表性，也保留权重带来的不确定性。</p><label>工作邮箱<input v-model="email" type="email" required autocomplete="username"/></label><label>密码<input v-model="password" type="password" required autocomplete="current-password"/></label><ErrorNotice :message="error" @retry="submit"/><button class="primary" :disabled="busy">{{busy?'正在进入…':'打开研究票据 →'}}</button><aside>演示角色：admin / analyst / viewer @balance.demo<br>统一密码：Balance2026!</aside></form></div></template>
